  /**
   * markdown 格式的 report 内容。
   */
  content_markdown: string;
  /**
   * report artifact 状态。
   */
  status: 'draft' | 'generated' | 'archived';
  /**
   * report artifact 版本。
   */
  version: number;
  /**
   * report 创建时间。
   */
